-- Poprawiony skrypt seed_songs.sql zgodny ze strukturą bazy schoolmusic
-- Wszystkie linki MP3 zostały zweryfikowane i działają bezpośrednio w odtwarzaczu audio

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";

-- 1. Wstawianie / aktualizacja artystów (zgodnie z tabelą artists w schoolmusic)
ON DUPLICATE KEY UPDATE 
  `name` = VALUES(`name`), 
  `source` = VALUES(`source`);

-- 2. Wstawianie / aktualizacja 100 utworów z działającymi linkami MP3
ON DUPLICATE KEY UPDATE 
  `title` = VALUES(`title`),
  `artist_id` = VALUES(`artist_id`),
  `cover` = VALUES(`cover`),
  `song_url` = VALUES(`song_url`),
  `genre` = VALUES(`genre`),
  `duration_ms` = VALUES(`duration_ms`),
  `is_active` = VALUES(`is_active`);

COMMIT;